import fse from 'fs-extra'

import { logError, resolveToRoot, writeFile } from './build.utils.js'

const svgIconSetBanner = setName => `
/*
 * DO NOT EDIT THIS FILE. It is automatically generated
 * from its webfont counterpart (same filename without "svg-" prefix).
 * Edit that file instead (${setName}.js).
 */`

// generic conversion
const convert = str => str.replaceAll(/(-\w)/g, m => m[1].toUpperCase())
const materialConvert = (str, old, prefix) => {
  if (old !== '') {
    str = str.slice(old.length)
  }
  return (prefix + str).replaceAll(/(_\w)/g, m => m[1].toUpperCase())
}

const iconTypes = [
  {
    name: 'material-icons-outlined',
    regex: /^o_/,
    convert: str => materialConvert(str, 'o_', 'outlined_')
  },
  {
    name: 'material-icons-round',
    regex: /^r_/,
    convert: str => materialConvert(str, 'r_', 'round_')
  },
  {
    name: 'material-icons-sharp',
    regex: /^s_/,
    convert: str => materialConvert(str, 's_', 'sharp_')
  },
  {
    name: 'material-symbols-outlined',
    regex: /^sym_o_/,
    convert: str => materialConvert(str, 'sym_o_', 'sym_outlined_')
  },
  {
    name: 'material-symbols-rounded',
    regex: /^sym_r_/,
    convert: str => materialConvert(str, 'sym_r_', 'sym_rounded_')
  },
  {
    name: 'material-symbols-sharp',
    regex: /^sym_s_/,
    convert: str => materialConvert(str, 'sym_s_', 'sym_sharp_')
  },
  {
    name: 'mdi-v7',
    regex: /^mdi-/,
    convert
  },
  {
    name: 'ionicons-v4', // last web font version
    regex: /^ion-/,
    convert: str =>
      convert(/ion-(md|ios)-/.test(str) ? str : str.replace(/ion-/, 'ion-md-'))
  },
  {
    name: 'fontawesome-v7',
    regex: /^fa[brs] fa-/,
    convert: str => convert(str.replace(' fa-', '-'))
  },
  {
    name: 'eva-icons',
    regex: /^eva-/,
    convert
  },
  {
    name: 'themify',
    regex: /^ti-/,
    convert
  },
  {
    name: 'line-awesome',
    regex: /^la[brs] la-/,
    convert: str =>
      convert(
        (str.startsWith('las la-') ? str + '-solid' : str).replace(
          /^la[brs] la-/,
          'la-'
        )
      )
  },
  {
    name: 'bootstrap-icons',
    regex: /^bi-/,
    convert
  },
  // must be last as it's a catch-all
  {
    name: 'material-icons',
    regex: /./,
    convert: str => materialConvert(str, '', 'mat_')
  }
]

// material-icons is the canonical icon-set shape. Optional editor entries are
// declared by the public type and fall back at runtime when a pack omits them.
const optionalPaths = new Set([
  // fallbacks to editor.heading
  'editor.heading1',
  'editor.heading2',
  'editor.heading3',
  'editor.heading4',
  'editor.heading5',
  'editor.heading6',

  // fallbacks to editor.size
  'editor.size1',
  'editor.size2',
  'editor.size3',
  'editor.size4',
  'editor.size5',
  'editor.size6',
  'editor.size7'
])

function getType(value) {
  return Array.isArray(value) ? `array:${value.length}` : typeof value
}

// Compare nested icon-set objects as "section.key" paths. This mirrors the
// language audit approach and catches missing, renamed, or incorrectly typed
// icon entries without maintaining a second schema by hand.
function flatten(obj, prefix = '') {
  const entries = new Map()

  for (const [key, value] of Object.entries(obj)) {
    const path = prefix === '' ? key : `${prefix}.${key}`

    if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
      for (const entry of flatten(value, path)) {
        entries.set(entry[0], entry[1])
      }
    } else {
      entries.set(path, value)
    }
  }

  return entries
}

function convertWebfont(name, originalType) {
  const type = originalType.regex.test(name)
    ? originalType
    : iconTypes.find(item => item.regex.test(name)) || iconTypes[0]

  return {
    importName: type.name,
    variableName: type.convert(name)
  }
}

function toObject(arr) {
  const obj = {}
  arr.forEach(item => {
    obj[item] = []
  })
  return obj
}

const iconNames = iconTypes.map(type => type.name)

const splitDelimiter = 'export default {'

function splitContent(str) {
  const content = str.split(splitDelimiter)

  return {
    outsideOfExport: content[0],
    insideOfExport: splitDelimiter + content[1]
  }
}

function validateIconSetShape(filename, iconSet, expectedPaths) {
  const paths = flatten(iconSet)

  if (iconSet.name !== filename.slice(0, -3)) {
    throw new Error(
      `${filename}: name should match filename; found ${iconSet.name}`
    )
  }

  for (const [path, expectedValue] of expectedPaths) {
    if (!paths.has(path)) {
      throw new Error(`${filename}: missing ${path}`)
    }

    const value = paths.get(path)
    const type = getType(value)
    const expectedType = getType(expectedValue)

    if (type !== expectedType) {
      throw new Error(
        `${filename}: ${path} is ${type}; expected ${expectedType}`
      )
    }

    if (path !== 'name' && typeof value === 'string' && value.length === 0) {
      throw new Error(`${filename}: ${path} must be a non-empty string`)
    }
  }

  for (const path of paths.keys()) {
    if (!expectedPaths.has(path) && !optionalPaths.has(path)) {
      throw new Error(`${filename}: unknown ${path}`)
    }
  }
}

function generateSvgFile(type) {
  const original = fse.readFileSync(
    resolveToRoot(`icon-set/${type.name}.js`),
    'utf8'
  )
  const { outsideOfExport, insideOfExport } = splitContent(original)

  const importList = toObject(iconNames)

  const contentString = insideOfExport
    .replace(/name: '(.+)'/, 'name: ""')
    .replaceAll(/'(.+)'/g, (_match, name) => {
      const { importName, variableName } = convertWebfont(name, type)
      if (!importList[importName].includes(variableName)) {
        importList[importName].push(variableName)
      }
      return variableName
    })
    .replace(/name: ""/, `name: 'svg-${type.name}'`)

  const importString = Object.keys(importList)
    .filter(listName => importList[listName].length !== 0)
    .map(
      listName =>
        'import {\n  ' +
        importList[listName].join(',\n  ') +
        `\n} from '@quasar/extras/${listName}'`
    )
    .join('\n\n')

  const content = [
    svgIconSetBanner(type.name),
    importString,
    outsideOfExport,
    contentString
  ]
    .filter(Boolean)
    .join('\n\n')

  const iconFile = resolveToRoot(`icon-set/svg-${type.name}.js`)

  let oldContent = ''

  try {
    oldContent = fse.readFileSync(iconFile, 'utf8')
  } catch {}

  return content.split(/[\n\r]+/).join('\n') !==
    oldContent.split(/[\n\r]+/).join('\n')
    ? writeFile(iconFile, content)
    : Promise.resolve()
}

export async function generate() {
  try {
    const expectedPaths = flatten(
      await import(resolveToRoot('icon-set/material-icons.js')).then(
        module => module.default
      )
    )

    for (const type of iconTypes) {
      const filename = `${type.name}.js`

      // also validates import statements from q/extras are valid
      const { default: iconSet } = await import(
        resolveToRoot(`icon-set/${filename}`)
      )

      validateIconSetShape(filename, iconSet, expectedPaths)

      await generateSvgFile(type)

      // validates import statements from q/extras are valid
      await import(resolveToRoot(`icon-set/svg-${filename}`))
    }
  } catch (err) {
    logError('build.icon-sets.js: something went wrong...')
    console.log()
    console.error(err)
    console.log()
    process.exit(1)
  }
}
